#include <cstddef>
#include <cstdint>
#include <span>
#include <string>
#include <string_view>
#include <unordered_set>
#include <vector>

// 1
[[nodiscard]] std::int64_t sum(std::span<const int> v) {
  std::int64_t s = 0;
  for (const int x : v) s += x;
  return s;
}

// 2
[[nodiscard]] bool has_duplicate_pairwise(std::span<const int> v) {
  for (std::ptrdiff_t i = 0; i < std::ssize(v); ++i)
    for (std::ptrdiff_t j = i + 1; j < std::ssize(v); ++j)
      if (v[i] == v[j]) return true;
  return false;
}

// 3
[[nodiscard]] int halvings(int n) {
  int steps = 0;
  while (n > 1) {
    n /= 2;
    ++steps;
  }
  return steps;
}

// 4
[[nodiscard]] bool has_duplicate_hashed(std::span<const int> v) {
  std::unordered_set<int> seen;
  for (const int x : v)
    if (!seen.insert(x).second) return true;
  return false;
}

// 5
[[nodiscard]] std::string repeat(std::string_view s, int k) {
  std::string out;
  for (int i = 0; i < k; ++i) out += s;
  return out;
}

int main() {
  const std::vector<int> v{3, 1, 4, 1, 5};
  const bool ok = sum(v) == 14 && has_duplicate_pairwise(v) && halvings(8) == 3 && has_duplicate_hashed(v) &&
                  repeat("ab", 3) == "ababab";
  return ok ? 0 : 1;
}

