#include <cstdint>
#include <format>
#include <iostream>

int main() {
  constexpr int n = 1024;
  std::int64_t nested = 0;
  std::int64_t doubling = 0;
  for (int i = 0; i < n; ++i)  // the inner loop runs i times
    for (int j = 0; j < i; ++j) ++nested;
  for (int i = 1; i < n; i *= 2)  // the inner loop also runs i times, but i doubles
    for (int j = 0; j < i; ++j) ++doubling;
  std::cout << std::format("nested: {} steps, doubling: {} steps\n", nested, doubling);
}

#include <chrono>
#include <concepts>
#include <cstddef>
#include <format>
#include <iostream>
#include <numeric>
#include <span>
#include <unordered_set>
#include <vector>

[[nodiscard]] bool has_duplicate_pairwise(std::span<const int> v) {
  for (std::ptrdiff_t i = 0; i < std::ssize(v); ++i)
    for (std::ptrdiff_t j = i + 1; j < std::ssize(v); ++j)
      if (v[i] == v[j]) return true;
  return false;
}

[[nodiscard]] bool has_duplicate_hashed(std::span<const int> v) {
  std::unordered_set<int> seen;
  for (const int x : v)
    if (!seen.insert(x).second) return true;
  return false;
}

struct Timed {
  bool found;
  std::chrono::duration<double, std::milli> elapsed;
};

// Runs check(v) once. The answer comes back with the time, so the caller uses it and the call can't be dropped.
[[nodiscard]] Timed timed(std::predicate<std::span<const int>> auto check, std::span<const int> v) {
  const auto start = std::chrono::steady_clock::now();
  const bool found = check(v);
  return {.found = found, .elapsed = std::chrono::steady_clock::now() - start};
}

int main() {
  for (const int n : {1000, 2000, 4000, 8000}) {
    std::vector<int> v(n);
    std::iota(v.begin(), v.end(), 0);  // 0, 1, 2, ...: no duplicates, the worst case
    const Timed pairwise = timed(has_duplicate_pairwise, v);
    const Timed hashed = timed(has_duplicate_hashed, v);
    std::cout << std::format("n = {:4}  pairwise {:7.2f} ms  hashed {:5.2f} ms  duplicates: {}\n", n,
                             pairwise.elapsed.count(), hashed.elapsed.count(), pairwise.found || hashed.found);
  }
}

#include <cstdint>
#include <format>
#include <iostream>
#include <numeric>
#include <ranges>
#include <vector>

struct Counted {
  explicit Counted(int v) : value(v) {}
  Counted(Counted&& other) noexcept : value(other.value), moves(other.moves + 1) {}

  int value;
  std::int64_t moves = 0;
};

int main() {
  std::vector<Counted> v;
  auto last = v.capacity();
  for (int i = 1; i <= 20; ++i) {
    v.emplace_back(i);
    if (v.capacity() != last) {
      last = v.capacity();
      std::cout << std::format("size {:2} -> capacity {}\n", v.size(), last);
    }
  }
  const auto moves = v | std::views::transform(&Counted::moves);
  std::cout << std::format("20 pushes made {} moves; element 1 moved {} times, element 20 {} times\n",
                           std::accumulate(moves.begin(), moves.end(), std::int64_t{0}), v.front().moves,
                           v.back().moves);
}

#include <cstdint>
#include <format>
#include <iostream>
#include <vector>

struct Counted {
  explicit Counted(int v) : value(v) {}
  Counted(const Counted& other) : value(other.value), copies(other.copies + 1), moves(other.moves) {}
  Counted(Counted&& other) : value(other.value), copies(other.copies), moves(other.moves + 1) {}  // not noexcept

  int value;
  std::int64_t copies = 0;
  std::int64_t moves = 0;
};

int main() {
  std::vector<Counted> v;
  for (int i = 1; i <= 20; ++i) v.emplace_back(i);
  std::int64_t copies = 0;
  std::int64_t moves = 0;
  for (const Counted& c : v) {
    copies += c.copies;
    moves += c.moves;
  }
  std::cout << std::format("moves {}, copies {}\n", moves, copies);
}
